```javascript
import * as THREE from 'three/webgpu';
import { color, mix, float, vec3 } from 'three/tsl';
import gsap from 'gsap';
import { createFontAtlasText } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'stat-tile-home';
  group.position.set(-2.5, 1.6, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const palette = {
    ink: new THREE.Color('#16161d'),
    paper: new THREE.Color('#e8ecf2'),
    accent: new THREE.Color('#ff2a38'),
    surface: new THREE.Color('#0b0b10'),
  };

  const disposables = [];
  const timelines = [];

  // Backing plate (machined surface) in case GLB is slow / as base card
  const plateGeo = new THREE.BoxGeometry(1.4, 0.9, 0.08);
  const plateMat = new THREE.MeshPhysicalNodeMaterial({
    color: palette.surface,
    metalness: 0.45,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
  });
  plateMat.colorNode = mix(color(palette.surface), color(palette.ink), float(0.3));
  const plate = new THREE.Mesh(plateGeo, plateMat);
  plate.name = 'stat-tile-plate';
  group.add(plate);
  disposables.push(plateGeo, plateMat);

  // Accent edge (focus indicator), hidden by default
  const edgeGeo = new THREE.BoxGeometry(1.44, 0.94, 0.06);
  const edgeMat = new THREE.MeshBasicNodeMaterial({ color: palette.accent, transparent: true, opacity: 0 });
  const edge = new THREE.Mesh(edgeGeo, edgeMat);
  edge.name = 'stat-tile-edge';
  edge.position.z = -0.02;
  group.add(edge);
  disposables.push(edgeGeo, edgeMat);

  // Mesh asset (gear) as decorative machined element
  const meshUrl = config?.assets?.meshUrl || '/prism-mock/orrery/meshes/gear-a.glb';
  let gearRoot = null;
  try {
    const gltf = ctx.glbLoader.load(meshUrl);
    if (gltf && gltf.scene) {
      gearRoot = gltf.scene;
      gearRoot.name = 'stat-tile-gear';
      gearRoot.scale.set(0.35, 0.35, 0.35);
      gearRoot.position.set(0.45, -0.25, 0.06);
      group.add(gearRoot);
    }
  } catch (e) {
    // fail silently, plate still renders
  }

  // Value + label text via font atlas
  const valueText = createFontAtlasText({
    text: '128',
    font: 'display',
    weight: 600,
    size: 0.34,
    color: palette.paper,
    fontAtlas: ctx.fontAtlas,
  });
  valueText.name = 'stat-tile-value';
  valueText.position.set(-0.55, 0.15, 0.05);
  group.add(valueText);
  disposables.push(valueText);

  const labelText = createFontAtlasText({
    text: 'PIECES CRAFTED',
    font: 'text',
    weight: 400,
    size: 0.09,
    color: palette.paper,
    fontAtlas: ctx.fontAtlas,
  });
  labelText.name = 'stat-tile-label';
  labelText.position.set(-0.55, -0.2, 0.05);
  group.add(labelText);
  disposables.push(labelText);

  // Apply cinematic primitives from config
  const primitivesConfig = config?.cinematicPrimitives || [];
  primitivesConfig.forEach((primitive) => {
    const fn = ctx.primitives?.[primitive.name];
    if (typeof fn === 'function') {
      fn(group, primitive.params || {});
    }
  });

  // Hover: rise-in (subtle lift)
  const baseY = group.position.y;
  let hoverTl = null;
  const onPointerOver = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, { y: baseY + 0.15, duration: 0.7, ease: 'power3.out' }, 0);
    hoverTl.to(edgeMat, { opacity: 0.6, duration: 0.3, ease: 'power2.out' }, 0);
    timelines.push(hoverTl);
  };
  const onPointerOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, { y: baseY, duration: 0.5, ease: 'power2.out' }, 0);
    hoverTl.to(edgeMat, { opacity: 0, duration: 0.3, ease: 'power2.out' }, 0);
    timelines.push(hoverTl);
  };

  // Click: press-down + emit navigation event
  const onClick = (event) => {
    const pressTl = gsap.timeline();
    pressTl.to(group.scale, {
      x: 0.97, y: 0.97, z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      yoyo: true,
      repeat: 1,
    });
    timelines.push(pressTl);

    if (ctx.emit) {
      ctx.emit('hub-home.select', { source: 'stat-tile-home', event });
    }
  };

  group.userData.handlers = {
    onPointerOver,
    onPointerOut,
    onClick,
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    if (hoverTl) hoverTl.kill();

    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });

    if (gearRoot) {
      gearRoot.traverse((child) => {
        if (child.isMesh) {
          child.geometry?.dispose();
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material?.dispose();
          }
        }
      });
    }

    group.clear();
  };

  return group;
}
